# pillar1_translations_part2.py - Handcrafted translations for CharacterArchiveContent items

TRANSLATIONS_ARCHIVE = {
    "CharacterArchiveContent.10303.2": "Tốc Độ Gõ Phím\n\nTên Tài Liệu: Dân Novian và Cự Tháp\nSố Từ: 1413\nThời Gian: 4:33\nTốc Độ Trung Bình: 310 WPM\nTốc Độ Đỉnh Điểm: 352 WPM\nĐộ Chính Xác: 99.8%\n\nĐánh Giá Hiệu Năng:\nBàn phím cơ mới mua gõ rất sướng tay, độ nảy phím cực tốt. Trừ phi có mèo chạy nhảy làm phiền, nếu không thì một ngày có thể xử lý xong ít nhất năm bản báo cáo kiểm toán.",

    "CharacterArchiveContent.10305.2": "Ghi Chú Điện Thoại: Đánh Giá Các \"Góc Trú Ẩn\"\n\nĐộ Thoải Mái:\n1. Xà Ngang Đại Sảnh Hiệp Hội Lữ Khách: Bình thường\nƯu điểm: Dễ ẩn mình, tầm quan sát rộng rãi.\nNhược điểm: Bụi bặm bám nhiều, thỉnh thoảng có người nhìn lên.\n2. Khe Hở Giữa Các Thùng Hàng Cảng Emor: Rất tốt\nƯu điểm: Thoang thoảng mùi cá biển, có bóng râm mát rượi, mèo con hay ghé qua tụ tập.\nNhược điểm: Thỉnh thoảng bị phu bốc vác dời thùng đi mất tiêu.\n3. Góc Phòng Lưu Trữ Lữ Đoàn Tân Tinh: Xuất sắc\nƯu điểm: Ấm áp, yên tĩnh, có đệm êm, không ai quấy rầy ngoại trừ Boss.",

    "CharacterArchiveContent.10306.2": "Ghi Chú Điện Thoại: \"Chiến Tích Máy Gắp Thú\"\n\nNhật Ký Đấu Trí Với Máy Gắp Thú\n1. Đối đầu \"Bá Chủ Gắp Gấu\" Nazuna\nTỉ số: 109 - 58\nMáy gắp ở tiệm này xịn thật, lực kẹp của càng gắp rất khỏe. Tuyệt cú mèo!\nĐấu xong, Nazuna vừa khóc vừa cười. Ủa... rốt cuộc là cô ấy đang vui hay buồn vậy ta?\n2. Đối đầu Jackpipi - \"Vua Gắp Thú Thành Phố Emor\"\nTỉ số: 10 - 0\nCàng gắp của chiếc máy này lỏng lẻo dễ sợ, chỉ tổ hất gấu văng lung tung.\nMình chỉ buột miệng hỏi: \"Anh có chắc mình là Vua Gắp Thú Emor thật không dợ?\"\nThế là Jackpipi òa khóc nức nở... Ơ kìa, mình nói gì sai sao?\n3. Đối đầu Mimi - \"Chuyên Gia Máy Gắp Thành Phố Philae\"\nTỉ số: 56 - 56\nHòa nhau. Cả hai đứa cùng nhẵn túi xu gắp.\nQuả không hổ danh chuyên gia, tay nghề rất cừ.\nHai bên đã hẹn tái đấu một trận sinh tử ngay khi kiếm thêm được tiền tiêu vặt.",

    "CharacterArchiveContent.10311.2": "Vào ngày sinh nhật của mình,\nAmber đã gom góp dành dụm đủ tiền để tự thưởng cho bản thân một suất đặc biệt tại quán cà phê mèo ở Khu Tro Tàn Emor.\n\nTối hôm ấy, nàng ngồi giữa một vòng vây những chú mèo tròn trĩnh mềm mại, trên đùi ấm áp tiếng thở rù quến rũ. Amber khẽ nhấp một ngụm trà sữa ngọt ngào, ánh mắt lấp lánh niềm vui bình dị.\nNàng thầm nghĩ, có lẽ đây chính là ngày sinh nhật hạnh phúc và êm đềm nhất từ trước đến nay.",

    "CharacterArchiveContent.10709.2": "Cực kỳ chuẩn xác. <sprite name=\"acrchives_certified_richtext\">\nGiữa các đội Lữ Khách luôn có một quy ước ngầm: Khi làm nhiệm vụ chung với Tilia, bạn tuyệt đối không bao giờ phải lo lắng về việc bị tập kích sau lưng.\nĐơn giản là vì, cô nàng sẽ luôn giơ khiên chắn ngay trước mũi bạn trước cả khi bạn kịp nhận ra nguy hiểm.",

    "CharacterArchiveContent.10810.2": "Phòng trò chơi bên trong Cự Tháp quả là một thiên đường kỳ diệu.\nNhững cỗ máy thùng arcade cổ điển to lớn ấy không phải là thứ dễ gì tìm thấy ngoài đời thực. Kasimira mỗi lần bước vào đây đều như biến thành một đứa trẻ, mắt sáng rực nhìn từng nút bấm và cần gạt.",

    "CharacterArchiveContent.11111.2": "\"Cho một hình tròn và hình vuông ngoại tiếp cùng quay quanh trục đối xứng chung, chúng sẽ tạo thành một hình trụ bao quanh một khối cầu...\"\nIris vừa cặm cụi phác thảo công thức hình học lên góc sổ vừa lẩm bẩm tính toán. Với cô, thế giới này vốn dĩ được vận hành bởi những định luật toán học tao nhã và hoàn mỹ nhất.",

    "CharacterArchiveContent.11112.2": "\"Nhiệm vụ của cô không phải là đưa ra lời khuyên thực tế đao to búa lớn, mà là giúp khách hàng được xoa dịu tâm hồn.\"\n\"M-Mát-xa tâm hồn á? Tôi tưởng mình nộp đơn làm chuyên viên tư vấn tài chính cơ mà?!\"\nIris hoang mang ôm tập hồ sơ, ngơ ngác nhìn vị tiền bối đang mỉm cười đầy ẩn ý.",

    "CharacterArchiveContent.11212.2": "\"Sự Tích Song Tinh Lạc Lối\" từng được đăng trên Tuyển Tập Kể Chuyện Lữ Khách của Hiệp Hội: Năm █, Ấn bản Tháng Gelu.\nNội dung kể về hai vì tinh tú ngỡ như vĩnh viễn chẳng thể chạm tới nhau, nhưng định mệnh lại đưa đẩy họ gặp gỡ nơi tận cùng của hành trình thám hiểm Cự Tháp.",

    "CharacterArchiveContent.11305.2": "Nhật Ký Shimiao ①\n\nShimiao có hoa tay vẽ bảng tin phấn màu cực kỳ đỉnh chóp. Hầu như toàn bộ các bảng thông báo dân cư quanh phố đều do một tay cô nàng trang trí, vừa bắt mắt, sinh động lại vừa chan chứa hơi ấm xóm giềng.",

    "CharacterArchiveContent.11306.2": "Nhật Ký Shimiao ②\n\nShimiao có niềm đam mê bất tận với các loại ớt cay nồng và nước sốt đặc chế.\nMỗi chiếc lọ trong gian bếp đều được cô cẩn thận dán nhãn ghi rõ ngày ủ, độ cay từ cấp một đến cấp mười, cùng lời cảnh báo nắn nót: \"Người không quen ăn cay xin chớ manh động!\"",

    "CharacterArchiveContent.11403.2": "Máy Chơi Game - Tổng Thời Gian Cày Cuốc\n\nHạng 1: Chaton Vĩ Đại (2.408,6 giờ)\nHạng 2: Kasimira (1.059,2 giờ)\nHạng 3: Benito (12,4 giờ)\n\nChaton tuyên bố: \"Thời gian dành cho game chính là minh chứng hùng hồn nhất cho đẳng cấp tối thượng của một bậc thầy gaming!\"",

    "CharacterArchiveContent.11404.2": "Máy Chơi Game - Bảng Xếp Hạng Đấu Hạng\n\nHạng 1: Kasimira\nHạng 2: Chaton Vĩ Đại\n...\nBenito: Chưa Xếp Hạng (Chưa đánh đủ số trận tối thiểu của mùa giải)\n\nChaton tức tối gào thét: \"Chỉ là Kasimira ăn may bấm bừa trúng nút thôi! Chờ đấy, lần sau bổn đại miêu nhất định sẽ phục thù!\"",

    "CharacterArchiveContent.11405.2": "Chiến Thư Của Thần Miêu\n\nTa—nhân danh Thần Meowth cổ đại tối cao—xin giáng lời phán xét!\nTrăng máu treo cao, tiếng chuông định mệnh đã điểm! Hỡi những kẻ phàm trần dám coi thường uy quyền của loài mèo, hãy run rẩy trước móng vuốt công lý!",

    "CharacterArchiveContent.11511.2": "\"Nghe đồn bạn học diện tuyển thẳng sống ở đây, Phòng 7 tầng 27... Ơ kìa? Cậu ấy không có nhà sao?\"\nBên ngoài cánh cửa đóng chặt, chỉ có tiếng máy móc vận hành rì rầm khe khẽ và ánh huỳnh quang mờ ảo hắt qua khe cửa.",

    "CharacterArchiveContent.11611.2": "Tháng Sonus, Ngày 3——\nHôm nay mình vừa khai hoang một mảnh đất thí nghiệm nhỏ xíu để ươm thử giống lúa mì chịu lạnh mới. Hy vọng mầm cây sẽ lớn thật nhanh và trổ bông trĩu hạt.",

    "CharacterArchiveContent.11810.2": "Hồ Sơ Điều Trị Bệnh Nhân Số ███\n\nHọ và Tên: ████\nTuổi: ██\nTháng █, Ngày █: Hai ngày sau khi khâu vết thương, tốc độ hồi phục nhanh đến kinh ngạc. Khả năng kiên cường chịu đựng của bệnh nhân thật phi thường—chắc chắn là đối tượng đáng để tiếp tục nghiên cứu sâu hơn.\nTháng █, Ngày █: Vết thương ngoài da gần như đã khép miệng hoàn toàn, nhưng các chỉ số sinh tồn của bệnh nhân vẫn thấp hơn mức trung bình. Khuyến nghị tiếp tục nằm tĩnh dưỡng thêm vài ngày.\n...\nTháng █, Ngày █: Trước khi xuất viện, tôi đã lấy ba ống máu tĩnh mạch của bệnh nhân. Kết quả phân tích xác nhận ██████. Cần tiếp tục theo dõi định kỳ.\n\nCoronis làm rơi hồ sơ bệnh án này tại Ốc Đảo May Mắn. Các trang còn lại đều bị bôi đen hoàn toàn. Boss à, rảnh thì ghé qua trả lại tài liệu này cho cô ấy nhé.\n—Iris",

    "CharacterArchiveContent.12010.2": "Tạm Dừng Điều Tra.\n\nTrong quá trình thẩm tra lý lịch của Canace, chúng tôi đã vấp phải sự can thiệp và cảnh báo gay gắt từ Ý Chí Ân Tứ.\nPhản ứng này càng chứng minh rõ những chi tiết về \"khoảng thời gian một năm biến mất\" của cô ấy là thông tin mật tuyệt đối ngay cả trong nội bộ Ý Chí Ân Tứ.\nDựa trên các công trình nghiên cứu đã công bố, rõ ràng Canace sở hữu kinh nghiệm dày dặn của một Lữ Khách kỳ cựu. Tuy nhiên, việc cô nàng kiên quyết từ chối thảo luận về vấn đề này làm dấy lên nhiều nghi ngại.\nTrước những điểm mờ mịt trong lý lịch của đối tượng, chúng tôi khuyến cáo nên thận trọng khi tiếp tục giao thiệp với cô ấy. <sprite name=\"acrchives_falsified_richtext\">\n—███, Hiệp Hội Lữ Khách",

    "CharacterArchiveContent.12510.2": "Trích đoạn từ một bài báo cũ.\n\nTin Độc Quyền! Luật Sư Gia Tộc Poitou Mất Tích Bí Ẩn!\nNguồn tin tiết lộ một nữ luật sư của gia tộc Poitou, người trước đó từng hành hung một người tham dự ngay tại phiên tòa, hiện đã bặt vô âm tín. Văn phòng luật của cô đã nhận được nhiều lá thư nặc danh yêu cầu một lời xin lỗi công khai.\nTính đến thời điểm hiện tại, gia tộc Poitou vẫn chưa đưa ra bất kỳ phản hồi chính thức nào về vụ việc...\n—Trích từ Nhật Báo Thành Phố Philae",

    "CharacterArchiveContent.12512.2": "Biên Bản Tòa Án (Trích yếu)\n\nPhiên tòa phúc thẩm vụ án tranh chấp di sản gia tộc Poitou:\n\"... Bị cáo đã có hành vi vi phạm nghiêm trọng trật tự phiên tòa, dùng tập hồ sơ dày cộp đánh vào đầu nguyên đơn... Luật sư Freesia khẳng định hành động trên là 'tự vệ chính đáng cho sự tôn nghiêm của pháp luật'...\"\nPhán quyết: Tạm đình chỉ hành nghề ba tháng để kiểm điểm tác phong.",

    "CharacterArchiveContent.12611.2": "Nhật Ký Nhà Kính Của Flora\n\nHôm nay những nụ hoa dạ lan hương đầu tiên đã bắt đầu hé nở. Hương thơm ngọt ngào lan tỏa khắp gian phòng kính.\nChỉ cần chăm sóc chúng bằng cả tấm lòng và sự dịu dàng, từng nhành hoa ngọn cỏ đều sẽ đáp lại bằng vẻ đẹp rực rỡ nhất.",

    "CharacterArchiveContent.12712.2": "Ghi Chép Về Đại Dương Của Teresa\n\nBiển cả bao la luôn ẩn chứa những giai điệu bí ẩn mà chỉ những tâm hồn tĩnh lặng mới có thể lắng nghe.\nMỗi con sóng vỗ bờ như một nốt nhạc trầm bổng, hòa cùng tiếng đàn ngân vang trong Cự Tháp tạo nên bản hòa ca bất tận.",

    "CharacterArchiveContent.13303.2": "Ghi Chú Nghiên Cứu Của Nazuka\n\nMôi trường bên trong Cự Tháp luôn biến đổi khôn lường theo từng tầng thử thách. Việc nắm vững quy luật phân bố của các dòng năng lượng nguyên tố chính là chìa khóa then chốt giúp các Lữ Khách sống sót trở về.",

    "CharacterArchiveContent.13307.2": "Sổ Tay Lữ Khách, Ấn Bản Thứ Ba — Tổng Biên Tập: Nazuka\n\n...\nTrích đoạn Kỹ Năng Sinh Tồn Nơi Hoang Dã — Cách Tìm Nguồn Nước:\nNguồn Tự Nhiên: Lần theo khe suối, bờ hồ lân cận, hoặc hứng nước từ rễ các loại thực vật mọng nước.\nPhương Pháp Lọc Sạch: Tự chế túi lọc dã chiến bằng vải, cát mịn và than củi; đun sôi nước sùng sục từ 3 đến 5 phút trước khi uống.\n...\nTrích đoạn Kỹ Năng Sinh Tồn Nơi Hoang Dã — Cách Dựng Lán Trú Ẩn:\nNguyên Tắc Chọn Địa Điểm: Chọn gò đất cao khuất gió, tuyệt đối tránh xa những thân cây mục khô và vách đá có nguy cơ sạt lở.\n...\nTrích đoạn Kỹ Năng Sinh Tồn Nơi Hoang Dã — Cách Kiếm Thức Ăn:\nDùng bẫy chai nhựa đục lỗ để bắt cá nhỏ dưới suối, đặt bẫy thòng lọng để bắt thú nhỏ trong bụi rậm. Hướng dẫn chi tiết cách chế tạo xin xem chương \"Nghệ Thuật Đặt Bẫy Dã Ngoại\".",

    "CharacterArchiveContent.13311.2": "Chuyện xảy ra trước khi Nazuka hạ quyết tâm thành lập đội săn tiền tiêu.\n...\n\"Chào cô Nazuka, lâu lắm không gặp. Lại ra rừng khảo sát tung tích ma thú đấy à?\"\n\"... Anh biết tôi sao?\"\n\"Dĩ nhiên rồi. Tôi thấy cô suốt mà. Lúc nào cũng đầu tắt mặt tối từ sáng sớm tinh mơ đến tối mịt, xông xáo cứu người thoát khỏi nanh vuốt ma thú... Dạo này danh tiếng của cô lan truyền nhanh lắm đấy nhé!\"\nNgười lạ mặt chủ động tự giới thiệu bản thân.\n\"Năm xưa cô từng cứu mạng tôi, nay tôi ghé qua để nói lời cảm ơn. Chút quà mọn này xin biếu cô làm kỷ niệm.\"\n\"Không cần đâu, anh cứ giữ lấy mà phòng thân. Dạo này các Lữ Khách kiếm sống khó khăn lắm.\"\n\"Ha ha.\" Anh nở nụ cười mệt mỏi đượm buồn. \"Đúng thật. Thế nên hôm nay tôi đến đây cũng là để nói lời từ biệt. Tôi sắp rời khỏi Thành Phố Philae để tìm vận may ở xứ khác.\"\n\"Hả...\"\n\"Chuyến săn vừa rồi của đội tôi thất bại thảm hại. Doanh trại bị quái vật giày xéo tan tành hết lần này đến lần khác... Một Lữ Khách quèn như tôi chẳng thể nào bám trụ nổi ở Philae này nữa rồi.\"\nNazuka lặng thinh không nói nên lời.\n\"Tạm biệt cô nhé, tiểu thư Nazuka. Cô khác xa những kẻ tầm thường như tôi. Cô mạnh mẽ, kiên cường và chưa từng dao động. Tôi thật lòng cầu chúc cô sẽ chạm tới thành công.\"\n\nNazuka không hề cất lời giữ anh lại. Nhưng chính vào ngày hôm ấy, cô đã nhớ lại lý do thuở ban đầu thôi thúc mình trở thành một Lữ Khách—và cuối cùng, cô cũng biết rõ bước tiếp theo mình cần phải làm gì.",

    "CharacterArchiveContent.13312.2": "05:00\nĐêm qua không có ma thú tập kích. Trạm gác phía tây báo cáo thiếu hụt tên bắn. Phát hiện một tân binh bôi nhầm các loại thuốc mỡ khác nhau. Cần sớm sắp xếp một buổi huấn luyện tập trung cho cả đội.\n...\n07:30\nPhát hiện vài chiếc lều cũ bị rách trong lúc đi tuần. Kiểm tra cho thấy không có vấn đề về chất lượng vải, đơn giản là chất liệu đã quá đát do là hàng tồn kho cũ từ Hiệp Hội Lữ Khách. Cần bổ sung thêm lều bạt dự phòng vào đợt tiếp tế tới.\n...\n08:30\nĐội hậu cần xảy ra xích mích với các thương nhân trong thành phố. Sau khi hòa giải, mâu thuẫn đã tạm thời lắng xuống. Cần soạn thảo phương án dự phòng để tránh tái diễn những sự cố tương tự.\n...\n10:00\nĐội trinh sát đã hoàn thành bản đồ sơ bộ về sự phân bố của ma thú trong khu vực săn bắn.\n...\n14:00\nMột cơn mưa rào bất chợt làm ngập lụt một góc doanh trại. May mắn thay, các biện pháp chống thấm và rãnh thoát nước đã phát huy hiệu quả tốt.\n...\n15:00\nTrời vẫn chưa dứt mưa. Ra lệnh cho toàn bộ thành viên ở yên trong doanh trại, ngoại trừ những người đang làm nhiệm vụ tuần tra.\n...\n22:00\nKiểm tra sau bão phát hiện ba mương thoát nước bị tắc nghẽn. Hiện các rãnh này đã được khơi thông hoàn toàn.\n...\n23:50\nHoàn thành lượt đổi ca gác đêm. Đã đến lúc nghỉ ngơi. Ngày mai chắc chắn sẽ còn bận rộn hơn nữa.",

    "CharacterArchiveContent.13701.2": "Tên: Eleanor\nSinh Nhật: 24 tháng 3\nTrực Thuộc: Lữ Khách Tự Do\nSở Trường: Hội Họa, Thẩm Định Châu Báu và Chiến Đấu Tự Do\nNơi Ở: Trang Viên Gia Tộc Fitzroy, Khu Vàng, Thành Phố Emor\nKinh Nghiệm Lữ Khách: Ba tháng\nVũ Khí: Vạn Tượng Hạp\nThù Lao: Những ủy thác thú vị sẽ được làm miễn phí",

    "CharacterArchiveContent.13405.2": "Sổ Tay Nấu Ăn\n\nBí quyết để nấu một bát canh miso thanh ngọt chính là phải canh lửa thật chuẩn và không được nêm gia vị quá sớm.\nHy vọng sư phụ sẽ thích món canh này khi nếm thử!",

    "CharacterArchiveContent.13411.2": "Nhật Ký Luyện Kiếm Của Fuyuka\n\n\"Luyện kiếm ngàn lần, dụng kiếm một khắc.\"\nLời dạy của sư phụ vẫn luôn in sâu trong tâm trí. Mỗi ngày vung kiếm một nghìn lần, dẫu mồ hôi ướt đẫm áo nhưng chỉ cần nghĩ đến ngày được sát cánh bảo vệ người, mọi mệt nhọc đều tan biến.",

    "CharacterArchiveContent.13511.2": "Bản Thảo Tin Tức Của Mistique\n\nThế gian này tràn ngập những lời dối trá ngọt ngào, nhưng công chúng xứng đáng được biết sự thật trần trụi phía sau tấm màn nhung.\nNhững con rối của tôi đã thu thập đủ bằng chứng, và bài phóng sự này sẽ là phát súng vạch trần tất cả.",

    "CharacterArchiveContent.13704.2": "Lịch Trình Sinh Hoạt Của Eleanor\n\nSáng: Đọc kỳ thư cổ và uống trà hoa cúc.\nChiều: Dạo quanh thư viện hoặc nhận vài ủy thác thú vị.\nTối: Quan sát các vì tinh tú và ghi chép chiêm tinh.\nLưu ý: Tuyệt đối không tiếp những vị khách thô lỗ và ồn ào.",

    "CharacterArchiveContent.13912.2": "\"Thơm quá xá luôn...\"\n\"Bộ có tiệm bánh mới mở gần đây hả tụi mày?\"\n\"Đừng có ngốc thế! Bánh mì làm gì có mùi thơm ngào ngạt thế này!\"\nMùi thức ăn thơm nức mũi luồn qua khe cửa bếp khiến đám nhóc đang đói meo trong phòng ăn bắt đầu nhấp nhổm không yên.\n\n\"Nè, mẹ về chưa dạ?\"\n\"Suỵt! Đã bảo đừng gọi mẹ rồi mà, phải gọi là dì Allie!\"\n\"Em thấy dì Allie chưa về đâu...\"\n\"Ủa, thế ai đang nấu ăn trong trỏng vậy?\"\nĐó mới chính là câu hỏi mấu chốt. Dì Allie đã dặn dò kỹ lưỡng rằng hôm nay dì đi làm về muộn. Rõ ràng là có người lạ đang ở trong bếp!\n\n\"Ai ở trộm trong đó thế?!\"\nLấy hết can đảm, lũ trẻ ùa vào cửa bếp, sẵn sàng nghênh chiến với bất kỳ kẻ đột nhập nào.\n\n\"Amber! Đưa khoai tây đây cho tớ nào!\"\n\"Tới liền tới liền...\"\n\"Noya, tớ gọt vỏ cà chua xong rồi nè!\"\n\"Tuyệt vời ông mặt trời! Cảm ơn Iris nha!\"\nTrước mắt lũ trẻ là hình ảnh Noya đang đứng bên bếp lò, một tay cầm chiếc muôi to tướng khuấy đảo nồi hầm khổng lồ đang sôi sùng sục và tỏa ra mùi thơm ngào ngạt quyến rũ.\n\n\"Ủa, ngoài kia sốt ruột lắm rồi hả? Đợi xíu xiu nữa thôi, chín tới nơi rồi nè!\"\n\"Noya, cậu đang làm cái gì thế?\"\n\"Nấu bữa tối chứ làm gì nữa! Dì Allie đi làm cả ngày về chắc mệt lả người cho xem, nên tối nay tớ bao trọn gian bếp luôn!\"\n\"Bữa tối á? Ý cậu là cái nồi thơm nức mũi này thực sự ăn được á hả?\"\nĐám nhóc tụ tập quanh cửa, mắt tròn xoe nhìn Noya thản nhiên nêm nếm gia vị vào nồi nước dùng bốc khói.\nNàng thao tác thuần thục và nhẹ nhàng đến mức lũ trẻ chỉ biết há hốc mồm kinh ngạc:\nHóa ra gian bếp nhà mình cũng có thể làm ra món ăn thơm ngon nức nở nhường này sao?\n\n\"Xong xuôi rồi nè!\"\nSau khoảng thời gian chờ đợi tưởng chừng như vô tận, Noya giơ cao chiếc muôi và dõng dạc tuyên bố món ăn đã hoàn thành.\n\"Được rồi, mỗi người một muỗng nhé! Nhưng cấm được ăn sạch bách đó, phải để dành một phần thật ngon cho dì Allie nữa!\"\nBất chấp lời dặn dò, đám nhóc đói cồn cào húp lấy húp để món thịt hầm như nuốt trọn cả đĩa. Chiếc nồi to tướng sạch bóng kin kít chỉ trong chớp mắt.\nNoya cẩn thận múc phần thịt hầm ngon nhất còn lại vào một chiếc bát tô lớn, đặt ngay ngắn ở chính giữa bàn ăn.\n\nVài tiếng đồng hồ trôi qua, tiếng bước chân quen thuộc cuối cùng cũng vang lên ngoài hiên.\nKhi Allie đẩy cửa bước vào, đón chào nàng không phải là gian phòng ăn tối tăm lạnh lẽo như mọi khi, mà là chiếc bàn ăn ấm cúng ngổn ngang bát đĩa, xung quanh là lũ trẻ đang cười toe toét nhìn nàng rạng rỡ.\n\"Mừng dì đã về nhà ạ!\"\nChúng ríu rít ùa tới vây quanh trước cả khi nàng kịp cởi giày. Đứa thì đỡ lấy vũ khí, đứa thì kéo nàng ngồi vào ghế êm, và ai đó đã nhanh nhảu dúi thẳng chiếc bát thịt hầm ấm nóng thơm lừng vào tay nàng.\nSững sờ một thoáng, Allie chỉ biết đứng lặng. Ánh mắt nàng nhìn từ bát hầm nghi ngút khói sang từng gương mặt rạng rỡ của lũ trẻ, một nụ cười ấm áp dịu dàng bỗng nở bừng trên khóe môi.\n\"Mấy đứa... tự làm món này sao?\"\n\"Noya nấu chính đấy ạ!\"\n\"Chị Amber với Iris phụ một tay nữa!\"\n\"Tụi con để dành bát to nhất ngon nhất này riêng cho dì Allie đó nha!\"\nNgồi lặng lẽ nơi đầu bàn dài, Allie nhìn xuống bát canh hầm thơm phức rồi ăn miếng đầu tiên trong sự xúc động nghẹn ngào, đôi mắt dịu hiền chan chứa hơi ấm yêu thương.\nĐối với nàng, đây chính là bữa ăn hạnh phúc nhất mà cả đời này nàng chẳng bao giờ quên được.",

    "CharacterArchiveContent.14010.2": "Phiếu Mượn Sách Thư Viện\n\nTên Sách: Truyện Cổ Tích ■■■\nTác Giả: Khuyết Danh\nMã Số Lưu Trữ: I536.8\nNgày Mượn: 3 tháng 9, Năm ■■■\nNgày Hạn Trả: 17 tháng 9, Năm ■■■\nNgười Mượn: S\nNgày Trả Sách: 9 tháng 9, Năm ■■■\nGhi Chú: /",

    "CharacterArchiveContent.14401.2": "Tên: Chitose\nSinh Nhật: 3 tháng 11\nTrực Thuộc: Lữ Khách Tự Do\nSở Trường: Kiếm Thuật\nNơi Ở: Quán Trọ Amekiku\nLý Lịch: Nửa năm\nVũ Khí: Nữ Hoàng Lưỡi Kiếm\nThù Lao: Cơm no áo ấm là được (ưu tiên cơm trắng dẻo thơm).",

    "CharacterArchiveContent.14513.2": "\"Nghe đồn gì chưa? Có vị Lữ Khách đang lùng sục khắp hang cùng ngõ hẻm tìm thợ rèn binh khí đấy.\"\n\"Ừ, có nghe. Nghe bảo bản vẽ vũ khí của cô nàng dài tới hơn hai mươi trang lận. Thợ rèn nào nhìn qua cũng lắc đầu chạy mất dép. Cơ mà nghe nói thù lao cô ấy trả cũng khủng khiếp không kém.\"\n\"Thật tò mò không biết cô ấy định chế tạo thứ quái quỷ gì...\"\n\nOtoha đứng giữa ngã ba đường. Nàng rút tấm bản đồ nguệch ngoạc ra kiểm tra lại lộ trình, rồi rảo bước men theo con đường mòn nhỏ bên tay phải.\nĐây đã là người thợ rèn thứ bảy nàng ghé thăm trong tháng này. Cho đến giờ, mọi thợ rèn đều lịch sự từ chối ngay khi nàng trao bản thiết kế—dù nàng có đưa ra mức thù lao gấp mấy lần giá thị trường đi chăng nữa.\nNàng tự hỏi liệu người này có thèm kiên nhẫn nghe nàng nói hết câu hay không.\nGạt đi nỗi băn khoăn, Otoha gõ nhẹ lên cánh cửa căn chòi gỗ biệt lập.\n\nThật bất ngờ, người thợ rèn già nua chẳng hề tỏ ra nao núng. Khi nhận lấy xấp tài liệu thiết kế dày hai mươi ba trang từ tay nàng, đôi mắt ông lão bỗng sáng rực lên.\n\"Ta đợi cô mãi đấy,\" ông lão trầm ngâm lần giở từng trang. \"Khi nghe tin có kẻ cầm bản yêu cầu quái đản đi tìm thợ rèn khắp nơi, ta đã muốn biết kẻ đó là ai và định làm ra món đồ gì rồi.\"\nOtoha mỉm cười thầm. Ít nhất lần này nàng không bị tống cổ ra cửa ngay tắp lự.\n\"Vậy chắc ông cũng nghe nói thù lao không thành vấn đề rồi chứ? Tôi chỉ quan tâm duy nhất một điều: Liệu có thể rèn ra thứ này thật không?\"\n\"Trông thì phức tạp đấy, nhưng xét cho cùng thì cô bé chỉ muốn một khẩu súng thôi, đúng chứ?\"\n\"Hình dáng cuối cùng ra sao tôi không bận tâm. Nếu ông thấy nó cần là một khẩu súng, thì nó chính là súng.\"\n\"Ta hiểu rồi. Rất thẳng thắn.\"\nÔng lão bật cười khà khà rồi đưa trả tập giấy. Trái tim Otoha chợt chùng xuống, ngỡ rằng lại thêm một lời từ chối, nhưng rồi ông lão quay bước đi về phía bàn làm việc.\n\"Mớ ghi chép này của cô lộn xộn quá. Ngồi xuống đây đi. Để xem món đồ chơi này thực sự sẽ mang hình hài thế nào nào.\"\n\n...\nMột buổi chiều tà hai tháng sau, Otoha trang trọng cúi đầu cảm ơn người thợ rèn rồi nói lời từ biệt. Ông lão chỉ nhìn chằm chằm vào chiếc ô dài cán mảnh trên tay nàng rồi thở dài.\n\"Kỳ công rèn ra một nòng súng tuyệt mỹ nhường ấy, rốt cuộc cô bé lại giấu biệt tăm dưới tán dù vải.\"\nOtoha từ lâu đã thấu hiểu tính nết của ông cụ. Nàng mỉm cười đáp: \"Chính vì nó quá đẹp đẽ, nên mới càng phải giấu kín chứ ạ.\"\n\"Hừ, mồm mép cô lúc nào cũng lanh lợi hết phần thiên hạ,\" ông lão xua tay. \"Ta chỉ mong thứ vũ khí này sẽ giúp cô hoàn thành bất cứ tâm nguyện nào cô hằng ấp ủ.\"\n\"Chắc chắn rồi ạ. Cháu xin hứa với ông.\"",

    "CharacterArchiveContent.14712.2": "Thuở Caramel còn là một cô bé con, cha nàng thường dịu dàng kể cho nghe câu chuyện về \"Ca Sĩ Nửa Đêm\".\nGiai điệu ấy tựa như khúc hát ru đưa nàng vào những giấc mộng ngọt ngào, thắp lên trong tâm hồn nàng ngọn lửa đam mê bất tận với âm nhạc và những phím đàn bass.",

    "CharacterArchiveContent.14905.2": "Báo Cáo Đánh Giá Sức Khỏe Tâm Thần\n\n#Trung Tâm Sức Khỏe Tâm Thần Thành Phố Emor\n##Hồ Sơ Đánh Giá Tâm Lý Tổng Quát\nĐối tượng: Chitose\nKết luận sơ bộ: Trạng thái tinh thần ổn định, tuy có xu hướng suy nghĩ độc lập sâu sắc và phản ứng nhạy cảm với các yếu tố huyền bí. Khuyến nghị duy trì các hoạt động sáng tạo nghệ thuật để thư giãn tâm trí.",

    "CharacterArchiveContent.15611.2": "Khi con đường dẫn tới Cự Tháp mở cửa trở lại, các Lữ Khách lại hăm hở tiếp tục sứ mệnh khám phá của mình.\nNazuna đứng bên bờ vịnh nhìn theo những đoàn thuyền ra khơi, khóe môi nở nụ cười rạng rỡ đầy hy vọng.",

    "CharacterArchiveContent.15712.2": "Lạc vào vùng biển xa xôi chưa từng được khai phá ngoài khơi Cảng Sailstead, Karin thấy mình đối mặt với một hiểm cảnh kinh hoàng:\nMột con cá marlin khổng lồ to lớn tựa chiến xa Artifact bất ngờ phóng vút lên khỏi mặt biển, chắn ngang vầng thái dương và phủ bóng đen chết chóc xuống mũi thuyền!",

    "CharacterArchiveContent.15913.2": "Phải làm gì khi lỡ điều chế dư quá nhiều độc dược ma thuật?\nNhìn chiếc vạc đang sủi bọt ùng ục trước mắt, Coronis chỉ biết ôm trán thở dài: \"Xem ra lại phải đóng chai đem đi phát miễn phí cho mấy đứa nhóc tò mò rồi...\"",

    "CharacterArchiveContent.16006.2": "\"Đừng Dại Dột Chọc Giận Willow\"\n\nNhìn chung, Willow luôn toát lên vẻ đoan trang, dịu dàng và nhã nhặn như làn gió xuân. Nhưng một khi có kẻ dám cả gan làm tổn thương bạn bè hay vượt qua ranh giới của nàng, nàng sẽ cho kẻ đó biết thế nào là sự phẫn nộ đáng sợ của một đóa hồng có gai.",

    "CharacterArchiveContent.16201.2": "Tên: Alina\nSinh Nhật: 21 tháng 6\nTrực Thuộc: Dạ Nguyện Giả\nSở Trường: Kiếm Thuật\nNơi Ở: Filanis\nLý Lịch: ██\nVũ Khí: ██\nThù Lao: ██",

    "CharacterArchiveContent.16201.3": "Tên: Noya\nSinh Nhật: 21 tháng 6\nTrực Thuộc: Dạ Nguyện Giả\nSở Trường: Kiếm Thuật\nNơi Ở: Filanis\nLý Lịch: Không thể kiểm chứng\nVũ Khí: Bình Minh & Rạng Đông\nThù Lao: Không có",

    "CharacterArchiveContent.16202.1": "Lý Do Trở Thành Dạ Nguyện Giả",
    "CharacterArchiveContent.16202.2": "Bảo vệ Filanis và giành lấy tư cách được thực hiện một điều ước.",

    "CharacterArchiveContent.16203.1": "Trích Dẫn Hồ Sơ 1: Mục Tiêu Tiết Kiệm",
    "CharacterArchiveContent.16203.2": "Dạ Nguyện Giả không được nhận thù lao cố định, vì vậy Alina luôn tranh thủ nhận thêm việc làm thêm mỗi khi có thể.\nCô nàng dường như đang tích cóp tiền để mua một cỗ xe ngựa sau khi mọi chuyện rắc rối này kết thúc. Có vẻ như những câu chuyện của ==PLAYER_NAME== đã để lại ấn tượng sâu đậm trong lòng cô. Cô thậm chí còn dự định đặt tên cho chú ngựa là Loxy nữa cơ.",

    "CharacterArchiveContent.16204.1": "Trích Dẫn Hồ Sơ 2: Tài Nấu Nướng Của Alina",
    "CharacterArchiveContent.16204.2": "\"Em biết chị ấy là hiệp sĩ của chính nghĩa, nhưng tại sao đồ ăn chị ấy nấu lại đen ngòm và tà đạo như ma thuật hắc ám thế này trời?!\"\n—Lulu\n\nĐó là lời cảnh báo mà cái bóng nhỏ của Alina đã thầm thì với chúng tôi trước khi cả bọn kéo nhau đi dự tiệc mừng chiến thắng. Alina nghe thấy thì dỗi ra mặt. Cô nàng quyết tâm chứng minh mọi người đã sai bằng cách bưng ra một món ăn ít đen hơn nhưng... sặc sỡ đủ bảy sắc cầu vồng một cách kỳ dị.\nNếu lúc đó ==PLAYER_NAME== không kịp thời ra tay cứu nguy cho bữa tối, có lẽ tôi đã được diện kiến các vị thần ma pháp sớm hơn dự định rồi.",

    "CharacterArchiveContent.16205.1": "Trích Dẫn Hồ Sơ 3: Viên Ma Thạch",
    "CharacterArchiveContent.16205.2": "Alina dường như đã nhầm một viên xúc xắc hai mươi mặt thành một viên ma thạch ước nguyện. Cô tin chắc rằng chỉ cần mình kiên trì xoay nó trên tay đủ 999.990.000 lần, Thần Ma Pháp sẽ ban cho cô bất kỳ điều ước nào—không rõ cô nàng bị mê hoặc bởi đường nét tinh xảo của viên xúc xắc, hay nỗi khát khao biến điều ước thành hiện thực trong lòng cô đã quá đỗi sâu đậm rồi?",

    "CharacterArchiveContent.16206.1": "Trích Dẫn Hồ Sơ 4: Dạ Nguyện Giả",
    "CharacterArchiveContent.16206.2": "Cư dân trong thành Filanis có thái độ rất tồi tệ đối với Alina. Sự xuất hiện của cô đã cắt đứt nguồn thu béo bở của họ: Những Dạ Nguyện Giả tiền nhiệm vốn xuất thân từ dân bản địa trên đảo, họ không chỉ chữa cháy mà còn kiêm luôn việc phóng hỏa đốt tiệm của những thương nhân từ chối nộp phí bảo hộ phòng cháy.\n\nAlina đã thẳng tay trục xuất những kẻ bất hảo đó khỏi hàng ngũ, khiến cô trở thành Dạ Nguyện Giả hợp pháp duy nhất trong thành phố.\n\nNhững nô lệ được giải phóng bên ngoài đảo tuy kính trọng Dạ Nguyện Giả, nhưng sâu trong thâm tâm họ lại xem Alina như tầng lớp quý tộc thượng lưu cao vời vợi, chẳng ai dám thực sự mở lòng lại gần cô.\n\nRốt cuộc, Alina chỉ có thể một mình gặm nhấm nỗi cô đơn lạnh lẽo giữa đêm trường sâu thẳm...\n\nFilanis cần cô, nhưng Filanis chưa từng thuộc về cô.",

    "CharacterArchiveContent.16207.1": "Trích Dẫn Hồ Sơ 5: Về Những Cái Tên",
    "CharacterArchiveContent.16207.2": "Khi ==PLAYER_NAME== vừa tỉnh lại, ==SEX== đã gọi nhầm Alina thành \"Noya\", và sau đó còn gọi sai tên cô thêm vài lần nữa. Có lẽ chính vì Alina quá đỗi giống với Noya trong ký ức nên ==PLAYER_NAME== mới nhận nhầm như vậy.\n\nĐiều thực sự kỳ lạ là: Alina chẳng hề tỏ ra giận dỗi khi bị gọi sai tên. Cô nàng thực sự quá cưng chiều ==PLAYER_NAME== rồi.",

    "CharacterArchiveContent.16208.1": "Thư Tiến Cử",
    "CharacterArchiveContent.16208.2": "\"Gửi tới Dạ Nguyện Giả tận tụy, Filanis sẽ không bao giờ lãng quên những hy sinh và cống hiến lớn lao của cô.\"\n—Leita\n\n\"Thầy Elis bảo rằng ngay cả thường dân cũng có quyền viết thư tiến cử! Cơ hội hiếm có nghìn năm có một này! Thế thì em phải viết thật nhiều, thật nhiều lời hay ý đẹp để ca ngợi Đội Trưởng Alina mới được! Chị ấy là ngầu nhất, đỉnh nhất, ừm... em tạm thời chưa nghĩ ra từ nào xịn hơn...\"\n—Lulu",

    "CharacterArchiveContent.16209.1": "Bình Luận Hồ Sơ",
    "CharacterArchiveContent.16209.2": "Chuẩn xác 100%. <sprite name=\"acrchives_certified_richtext\">\nAlina là kẻ ngốc... à không không không, là vị hiệp sĩ chính trực và nhân hậu nhất trần đời!",

    "CharacterArchiveContent.16210.1": "Trích Dẫn Hồ Sơ 6: Sơ Yếu Lý Lịch",
    "CharacterArchiveContent.16210.2": "==PLAYER_NAME== đã gợi ý một khái niệm từ quê hương của ==SEX3== dùng để sắp xếp hồ sơ cá nhân, gọi là \"sơ yếu lý lịch\". Bản mẫu được thiết kế rất khoa học và gọn gàng, giúp quản lý thông tin một cách mạch lạc.",
    "CharacterArchiveContent.16210.3": "==PLAYER_NAME== đã gợi ý một khái niệm từ quê hương của ==SEX3== dùng để sắp xếp hồ sơ cá nhân, gọi là \"sơ yếu lý lịch\". Bản mẫu được thiết kế rất khoa học và gọn gàng, giúp quản lý thông tin một cách mạch lạc.",

    "CharacterArchiveContent.16211.1": "Hồi Ức 1: Tiếng Khóc Nơi Đấu Trường",
    "CharacterArchiveContent.16211.2": "Đứa trẻ sơ sinh cất tiếng khóc chào đời bằng tất cả sức bình sinh, tiếng khóc vang dội như thể đang tuyệt vọng chứng minh cho thế giới thấy sinh linh nhỏ bé ấy vẫn còn tồn tại giữa chốn lao tù tàn nhẫn này.",

    "CharacterArchiveContent.16212.1": "Hồi Ức 2: Số 18 và Số 103",
    "CharacterArchiveContent.16212.2": "Nhiều năm trước, trước khi vị đấu sĩ già từng chứng kiến sự ra đời của \"Số 18\" may mắn được nhắm mắt xuôi tay vì tuổi già, ông đã để lại một lời tiên tri:\n\"Đứa trẻ này một ngày nào đó sẽ thoát khỏi số phận đấu sĩ, khoác lên mình một cái tên đích thực và sống một cuộc đời huyền thoại. Nhưng chỉ vào những năm tháng cuối cùng của cuộc đời, con bé mới tìm thấy hạnh phúc chân chính.\"\nBan đầu, chẳng ai thèm bận tâm đến những lời mê sảng lẩm cẩm của ông lão. Nhưng khi \"Số 18\" thực sự bộc lộ thiên phú chiến đấu kinh người, mọi người mới bắt đầu hối hận vì sao năm xưa không đến cầu xin một lời chỉ dẫn từ nhà tiên tri già.\n\"Số 18\" sinh ra là đứa con của đấu trường, định sẵn thuộc về nơi đẫm máu này.\nNgay cả sau ba ngày nhịn đói đến kiệt quệ, cô bé vẫn chạy nhanh hơn bất kỳ đứa trẻ nào được ăn no mặc ấm. Đứng trước đối thủ giác đấu cao gấp đôi mình, cô vẫn có thể dễ dàng lướt ra sau lưng đối phương rồi quật ngã họ xuống đất.\nĐồng thời, cô bé dường như cũng sớm thấu hiểu lẽ đời. Ngay khi có thể tự đứng vững trên đôi chân của mình, cô đã chủ động giữ khoảng cách với nữ đấu sĩ từng nuôi nấng mình khôn lớn.\nKhông phải vì cô quên đi ơn nghĩa dưỡng dục, mà bởi cô từng tận mắt chứng kiến lũ khán giả quý tộc trên khán đài cố tình vung rải tiền vàng để ép hai anh em vừa cùng nhau hạ gục ma thú phải rút kiếm tàn sát lẫn nhau.\nNữ đấu sĩ đó là một trường hợp vô cùng hiếm hoi, một đấu sĩ nô lệ đã chuộc được tự do thành công. Vận may trên chiến trường của bà rất lớn, nhưng điều may mắn hơn cả chính là việc người lính gác bị thương ở đầu gối nhưng mang thân phận \"hiệp sĩ\" đã rủ lòng thương giơ tay giúp đỡ bà.\nThẻ số hiệu của nữ đấu sĩ được trao lại cho một tân binh rụt rè, và 18 đã ghi nhớ con số ấy: Số 103.\nRất nhanh sau đó, số phận đã an bài: Đối thủ tiếp theo của 18 chính là Số 103.\nTrận tử chiến nơi chỉ có duy nhất một người được phép sống sót bắt đầu. Số 103 trẻ tuổi nhanh chóng nhận ra rằng dù bản thân có tấn công điên cuồng đến đâu hay để lộ bao nhiêu sơ hở chết người, đối thủ đối diện chưa từng có một tia ý niệm muốn lấy mạng cô.\nTừ đầu đến cuối, lưỡi kiếm của Số 18 chỉ nhắm vào những vị trí không gây nguy hiểm tính mạng nhưng chảy nhiều máu, dù đối thủ của cô không hề nương tay như vậy.\nSố 103 không hiểu vì sao Số 18 lại làm thế. Cô chỉ biết chắc một điều: Bản thân tuyệt đối không có cửa chiến thắng trước Số 18.\nCô trơ mắt nhìn lưỡi kiếm cũ kỹ ấy đâm xuyên qua da thịt mình, lách qua mọi hiểm huyệt nội tạng, rồi trổ ra phía sau cùng một dòng máu đỏ thẫm bắn tung tóe.\nTiếng vỗ tay sấm dậy vang lên từ khắp các khán đài, và cô biết mình đã sống sót.\nTrước khi lịm đi vì kiệt sức, ý nghĩ duy nhất còn đọng lại trong tâm trí cô là: Khi tỉnh lại, nhất định phải nói một lời cảm ơn chân thành tới người ấy.",

    "CharacterArchiveContent.16213.1": "Món Quà Của Những Người Bạn",
    "CharacterArchiveContent.16213.2": "Mấy cô gái đứng tụ tập trước một lò rèn xập xệ cũ kỹ...\n\"Hừm... Cây này không được... Ôi, nặng quá xá...\"\n\"Yara, cậu đang làm cái trò gì thế?\"\n\"Ồ, Morgan. Chẳng phải rõ rành rành rồi sao? Tớ đang đi mua vũ khí nè.\"\n\"Cậu dùng khiên mà. Sao lại đi săm soi kiếm dài làm chi... Khoan đã, đừng nói với tớ là...\"\n\"Chuẩn luôn! Không phải mua cho tớ, mà là mua cho cậu ấy.\"\n\"Số 18 ấy hả... Sao cậu vẫn dây dưa nói chuyện với cậu ấy làm gì? Cậu ấy là một con nghiện chiến đấu cuồng sát đấy.\"\n\"Thế con nghiện chiến đấu ấy đã cứu mạng tụi mình không biết bao nhiêu lần rồi, đúng không nào?\"\n\"Thì cũng đúng... Nhờ cậu ấy mà vết thương của tớ mới mau lành, lại còn kiếm được hai tuần nghỉ dưỡng sức nữa chứ.\"\n\"Haizz, thôi được rồi! Tớ sẽ giúp cậu một tay. Nhưng trước hết vứt hết mớ phế liệu này đi đã. Toàn là đồ thừa nhặt nhạnh của mấy đấu sĩ đã chết thôi. Chẳng thể nào kiếm nổi một thanh kiếm ra hồn bên trong Đấu Trường đâu.\"\n\"Thế giờ biết tìm ở đâu bây giờ?\"\n\"... Hì, tớ có cách này. Yara, có muốn làm một chuyến dạo chơi ra ngoài không?\"\n\nSáu cô gái tụm lại thì thầm bên ngoài trạm gác...\n\n\"Bỏ tiền mua một giờ tự do á? Liệu trò này có ổn thật không đấy?\"\n\"Tin tớ đi, tớ thấy người ta làm suốt rồi. Có điều tụi mình phải đeo vòng cổ ma pháp. Hễ bước ra ngoài phạm vi cho phép là mất mạng như chơi đấy.\"\n\"Ở trong này không kiếm được thanh kiếm tử tế đâu. Tụi mình cần tìm một tiệm rèn thực thụ ở bên ngoài thành.\"\n\"Nhưng một giờ tự do tốn bao nhiêu tiền lận? Vả lại nghe nguy hiểm quá chừng...\"\n\"Yên tâm đi. Đâu phải chỉ mình cậu nợ cậu ấy một ân tình đâu.\"\n\"Tụi mình sẽ gom hết tiền dành dụm lại, đút lót cho tên đội trưởng lính gác, còn dư bao nhiêu thì dùng mua quà.\"\n\"Được rồi, tớ tin các cậu... Không biết Số 18 có thích món quà này không nữa.\"\n\nMáu tươi chảy dài loang lổ trên mặt đường lát đá...\n\n\"Khốn kiếp...! Khốn kiếp thật chứ...! Sao máu không chịu ngừng chảy thế này...!\"\n\"Xin lỗi, Yara... Tớ tính sai một bước rồi. Không ngờ đám khốn đó lại dùng ma pháp thiêu rụi cả ngọn giáo của tớ...\"\n\"Đừng nói nữa! Tớ sẽ cõng cậu về Đấu Trường ngay bây giờ!\"\n\"Hì, tụi tớ lại... làm phiền cậu rồi... Kệ tớ đi... Món quà đâu rồi?\"\n\"Tớ giữ kỹ lắm rồi. Ma pháp của chúng nó không đốt trúng được. Tất cả là tại tớ...! Là tớ làm lộ tung tích của cả bọn!\"\n\"Chuyện đã rồi, trách ai được chứ. Ai ngờ lại đụng mặt ngay toán tuần tra đêm cơ chứ...\"\n\"Yara... nghe tớ nói này. Đừng kể cho cậu ấy biết tụi mình lén trốn ra ngoài vì chuyện này nhé.\"\n\"Tính cậu ấy bướng bỉnh lắm. Tụi mình không muốn mỗi lần vung thanh kiếm đó lên, cậu ấy lại phải nặng lòng nhớ đến tụi mình đâu...\"\n\"Tớ biết rồi mà... Cậu mất nhiều máu quá rồi. Làm ơn đi, đừng nói nữa mà!\"\n\"Nói gì lạ vậy, tớ còn phải bước vào đấu trường nữa chứ...\"\n\"Nhìn cho kỹ đám con rối kia đi, và nhìn cho kỹ cái cách mà gã đó vung kiếm...\"\nCô gái đấu sĩ trẻ tuổi lịm đi trong vòng tay đồng đội. Máu tươi đọng lại trên nền đất thành một vũng mỏng manh, phản chiếu bầu trời ngập tràn ánh sao bao la mà chẳng một ai ở đó đoái hoài thưởng ngoạn.",
}
